    onCancel?: () => void;
    onStop?: () => void;
    actions?: ReactNode;
    icon?: ReactNode;
  };

type IslandStyles = ReturnType<typeof dynamicIslandVariants>;
type FeedbackState = "success" | null;

type DynamicIslandActivity = {
  variant: DynamicIslandVariant;
  title?: string;
  description?: string;
  time?: string;
  progress?: number;
  image?: string;
  isPlaying?: boolean;
  isActive?: boolean;
  onPlayPause?: () => void;
  onConfirm?: () => void;
  onCancel?: () => void;
  onStop?: () => void;
  actions?: ReactNode;
  icon?: ReactNode;
};

const islandTransition = {
  type: "spring",
  stiffness: 280,
  damping: 32,
  mass: 0.92,
} satisfies Transition;

const reducedTransition = { duration: 0 } satisfies Transition;

const contentVariants: Variants = {
  hidden: { opacity: 0, y: 2, scale: 0.992 },
  visible: {
    opacity: 1,
    y: 0,
    scale: 1,
    transition: { duration: 0.22, ease: [0.22, 1, 0.36, 1] },
  },
  exit: {
    opacity: 0,
    y: -2,
    scale: 0.995,
    transition: { duration: 0.16, ease: [0.32, 0, 0.67, 0] },
  },
};

const defaults: Record<
  DynamicIslandVariant,
  { title: string; description: string; time?: string }
> = {
  music: {
    title: "Midnight City",
    description: "M83",
  },
  timer: {
