    <motion.span
      className="relative grid size-full place-items-center"
      initial={shouldReduceMotion ? false : { scale: 0.72, opacity: 0 }}
      animate={{ scale: 1, opacity: 1 }}
      transition={
        shouldReduceMotion
          ? reducedTransition
          : { type: "spring", stiffness: 520, damping: 28, mass: 0.62 }
      }
    >
      <motion.span
        className="absolute size-full rounded-full bg-green-500/10"
        initial={shouldReduceMotion ? false : { scale: 0.65, opacity: 0.7 }}
        animate={
          shouldReduceMotion
            ? { opacity: 0.35 }
            : { scale: [0.72, 1.28], opacity: [0.42, 0] }
        }
        transition={
          shouldReduceMotion
            ? reducedTransition
            : { duration: 0.58, ease: [0.22, 1, 0.36, 1] }
        }
        aria-hidden="true"
      />
      <Check
        className={twMerge("relative size-5", styles.successText())}
        aria-hidden="true"
      />
    </motion.span>
  );
}

function TimerRing({
  active,
  compact,
}: {
  active?: boolean;
  compact?: boolean;
}) {
  const shouldReduceMotion = useReducedMotion();

  return (
    <span className="relative grid size-full place-items-center">
      <Clock3
        className={twMerge(compact ? "size-3.5" : "size-4")}
        aria-hidden="true"
      />
      <motion.svg
        className="pointer-events-none absolute inset-0 size-full"
        viewBox="0 0 48 48"
        aria-hidden="true"
        animate={
          shouldReduceMotion || !active
            ? { rotate: -90 }
            : { rotate: [-90, 270] }
        }
        transition={
          shouldReduceMotion || !active
            ? reducedTransition
            : { duration: 18, repeat: Infinity, ease: "linear" }
        }
      >
        <circle
          cx="24"
          cy="24"
          r="20"
          fill="none"
          stroke="currentColor"
          strokeOpacity="0.16"
          strokeWidth="3"
        />
        <motion.circle
          cx="24"
          cy="24"
          r="20"
          fill="none"
          stroke="currentColor"
          strokeLinecap="round"
          strokeWidth="3"
          initial={{ pathLength: 0 }}
          animate={
            active
              ? { pathLength: [0.64, 0.82, 0.64], opacity: [0.76, 1, 0.76] }
              : { pathLength: 0.28, opacity: 0.5 }
          }
          transition={
            shouldReduceMotion
              ? reducedTransition
              : {
                  duration: active ? 2.8 : 0.7,
                  repeat: active ? Infinity : 0,
                  ease: "easeInOut",
                }
          }
        />
      </motion.svg>
    </span>
  );
}

function ProgressNumber({ value }: { value: number }) {
  const shouldReduceMotion = useReducedMotion();

  return (
    <AnimatePresence mode="popLayout" initial={false}>
      <motion.span
        key={value}
        className="shrink-0 tabular-nums"
        initial={shouldReduceMotion ? false : { opacity: 0, y: 4 }}
        animate={{ opacity: 1, y: 0 }}
        exit={shouldReduceMotion ? undefined : { opacity: 0, y: -4 }}
        transition={{ duration: 0.16, ease: [0.22, 1, 0.36, 1] }}
      >
        {value}%
      </motion.span>
    </AnimatePresence>
  );
}

function IslandActionButton({
  label,
  children,
  onClick,
  tone = "default",
  styles,
}: {
  label: string;
  children: ReactNode;
  onClick?: () => void;
  tone?: "default" | "primary" | "destructive";
  styles: IslandStyles;
}) {
  const shouldReduceMotion = useReducedMotion();
  const toneClassName = {
    default: "",
    primary: "bg-primary text-primary-foreground hover:bg-primary/90",
    destructive:
      "bg-destructive text-primary-foreground hover:bg-destructive/90",
  }[tone];

  return (
    <motion.button
      type="button"
      aria-label={label}
      onClick={(event) => {
        event.stopPropagation();
        onClick?.();
      }}
      className={twMerge(styles.actionButton(), toneClassName)}
      whileHover={shouldReduceMotion ? undefined : { scale: 1.04 }}
      whileTap={shouldReduceMotion ? undefined : { scale: 0.94 }}
      transition={shouldReduceMotion ? reducedTransition : islandTransition}
    >
      {children}
    </motion.button>
  );
}

function CopyBlock({
  activity,
  styles,
  timer,
  eyebrow,
}: {
  activity: DynamicIslandActivity;
  styles: IslandStyles;
  timer?: boolean;
  eyebrow?: string;
}) {
  const copy = getActivityCopy(activity);

  return (
    <motion.span
      layout
      layoutId={`dynamic-island-${activity.variant}-copy`}
      className={styles.copy()}
      transition={islandTransition}
    >
      {eyebrow ? <p className={styles.eyebrow()}>{eyebrow}</p> : null}
      <p className={timer ? styles.timerTitle() : styles.title()}>
        {activity.variant === "recording"
          ? (activity.time ?? copy.time)
          : copy.title}
      </p>
      <p className={styles.description()}>
        {activity.variant === "recording" ? copy.title : copy.description}
      </p>
    </motion.span>
  );
}

function CompactContent({
  activity,
  mode,
  styles,
  scope,
  feedback,
}: {
  activity: DynamicIslandActivity;
  mode: "compact" | "minimal";
  styles: IslandStyles;
  scope: string;
  feedback: FeedbackState;
}) {
  const copy = getActivityCopy(activity);
  const progress = clampProgress(activity.progress);

  if (mode === "minimal") {
    return (
      <motion.div
        key={`${scope}-minimal-${feedback ?? activity.variant}`}
        layout
        className="flex items-center justify-center"
        variants={contentVariants}
        initial="hidden"
        animate="visible"
        exit="exit"
      >
        {feedback === "success" || progress >= 100 ? (
          <Check
            className={twMerge("size-4", styles.successText())}
            aria-hidden="true"
          />
        ) : activity.variant === "recording" ? (
          <RecordingDot compact />
        ) : (
          <ActivityIcon activity={activity} className="size-4" />
        )}
      </motion.div>
    );
  }

  return (
    <motion.div
      key={`${scope}-compact-${feedback ?? activity.variant}`}
      layout
      className={styles.compactContent()}
      variants={contentVariants}
      initial="hidden"
      animate="visible"
      exit="exit"
    >
      {feedback === "success" || progress >= 100 ? (
        <>
          <Check
            className={twMerge("size-4 shrink-0", styles.successText())}
            aria-hidden="true"
          />
          <span className={twMerge(styles.compactPill(), styles.successText())}>
            Done
          </span>
        </>
      ) : null}

      {feedback !== "success" && activity.variant === "music" ? (
        <>
          <MediaOrb
            activity={activity}
            styles={styles}
            layoutId={`${scope}-media`}
          >
            <ActivityIcon activity={activity} className="size-3.5" />
          </MediaOrb>
          <Equalizer active={activity.isPlaying} />
        </>
      ) : null}

      {feedback !== "success" && activity.variant === "timer" ? (
        <>
          <MediaOrb
            activity={activity}
            styles={styles}
            layoutId={`${scope}-media`}
          >
            <TimerRing active={activity.isActive} compact />
          </MediaOrb>
          <span className={styles.compactPill()}>
            {activity.time ?? copy.title}
          </span>
        </>
      ) : null}

      {feedback !== "success" && activity.variant === "recording" ? (
        <>
          <RecordingDot compact />
          <span className={styles.compactPill()}>
            {activity.time ?? copy.time ?? "00:00"}
          </span>
        </>
      ) : null}

      {feedback !== "success" && activity.variant === "progress" ? (
        <>
          <MediaOrb
            activity={activity}
            styles={styles}
            layoutId={`${scope}-media`}
          >
            <ActivityIcon activity={activity} className="size-3.5" />
          </MediaOrb>
          <span className={styles.compactPill()}>
            <ProgressNumber value={progress} />
          </span>
        </>
      ) : null}

      {feedback !== "success" &&
      (activity.variant === "notification" ||
        activity.variant === "confirm") ? (
        <>
          <ActivityIcon activity={activity} className="size-4 shrink-0" />
          <span className={styles.statusDot()} aria-hidden="true" />
        </>
      ) : null}
    </motion.div>
  );
}

function ExpandedContent({
  activity,
  styles,
  scope,
  feedback,
  onConfirmSuccess,
}: {
  activity: DynamicIslandActivity;
  styles: IslandStyles;
  scope: string;
  feedback: FeedbackState;
  onConfirmSuccess: () => void;
}) {
  const shouldReduceMotion = useReducedMotion();
  const copy = getActivityCopy(activity);
  const progress = clampProgress(activity.progress);
  const showSuccess = feedback === "success" || progress >= 100;

  if (showSuccess) {
    return (
      <motion.div
        key={`${scope}-success`}
        layout
        className={styles.expandedContent()}
        variants={contentVariants}
        initial={shouldReduceMotion ? false : "hidden"}
        animate="visible"
        exit="exit"
      >
        <MediaOrb
          activity={{ ...activity, variant: "confirm" }}
          styles={styles}
          layoutId={`${scope}-media`}
          expanded
          className={styles.successMedia()}
        >
          <SuccessMark styles={styles} />
        </MediaOrb>
        <span className={styles.copy()}>
          <motion.p
            className={twMerge(styles.title(), styles.successText())}
            initial={shouldReduceMotion ? false : { opacity: 0, y: 4 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ delay: 0.06, duration: 0.16 }}
          >
            Completed
          </motion.p>
          <p className={styles.description()}>{copy.description}</p>
          <span className="mt-2 block">
            <span className={styles.progressTrackSuccess()}>
              <motion.span
                className={styles.progressFillSuccess()}
                initial={{ width: "0%" }}
                animate={{ width: "100%" }}
                transition={
                  shouldReduceMotion
                    ? reducedTransition
                    : { duration: 0.42, ease: [0.22, 1, 0.36, 1] }
                }
              />
            </span>
          </span>
        </span>
      </motion.div>
    );
  }

  return (
    <motion.div
      key={`${scope}-expanded-${activity.variant}`}
      layout
      className={styles.expandedContent()}
      variants={contentVariants}
      initial={shouldReduceMotion ? false : "hidden"}
      animate="visible"
      exit="exit"
    >
      {activity.variant === "music" ? (
        <>
          <MediaOrb
            activity={activity}
            styles={styles}
            layoutId={`${scope}-media`}
            expanded
          >
            <ActivityIcon activity={activity} className="size-5" />
          </MediaOrb>
          <span className={styles.copy()}>
            <p className={styles.eyebrow()}>
              {activity.isPlaying ? "Now playing" : "Paused"}
            </p>
            <p className={styles.title()}>{copy.title}</p>
            <p className={styles.description()}>{copy.description}</p>
            <span className="mt-2 block">
              <span className={styles.progressTrack()}>
                <motion.span
                  className={styles.progressFill()}
                  initial={{ width: "24%" }}
                  animate={{ width: activity.isPlaying ? "64%" : "42%" }}
                  transition={{
                    duration: activity.isPlaying ? 5.5 : 0.35,
                    ease: "easeInOut",
                  }}
                />
              </span>
            </span>
          </span>
          <IslandActionButton
            label={activity.isPlaying ? "Pause music" : "Play music"}
            onClick={activity.onPlayPause}
            tone="primary"
            styles={styles}
          >
            {activity.isPlaying ? (
              <Pause className="size-4" aria-hidden="true" />
            ) : (
              <Play className="size-4 fill-current" aria-hidden="true" />
            )}
          </IslandActionButton>
        </>
      ) : null}

      {activity.variant === "timer" ? (
        <>
          <MediaOrb
            activity={activity}
            styles={styles}
            layoutId={`${scope}-media`}
            expanded
            pulse={activity.isActive}
          >
            <TimerRing active={activity.isActive} />
          </MediaOrb>
          <CopyBlock
            activity={activity}
            styles={styles}
            timer
            eyebrow={activity.isActive ? "Timer running" : "Timer paused"}
          />
          <span className={styles.mutedText()}>
            {activity.isActive ? "Running" : "Paused"}
          </span>
        </>
      ) : null}

      {activity.variant === "recording" ? (
        <>
          <MediaOrb
            activity={activity}
            styles={styles}
            layoutId={`${scope}-media`}
            expanded
          >
            <RecordingDot />
          </MediaOrb>
          <CopyBlock activity={activity} styles={styles} timer eyebrow="Live" />
          <IslandActionButton
            label="Stop recording"
            onClick={activity.onStop}
            tone="destructive"
            styles={styles}
          >
            <Square className="size-3.5 fill-current" aria-hidden="true" />
          </IslandActionButton>
        </>
      ) : null}

      {activity.variant === "progress" ? (
        <>
          <MediaOrb
            activity={activity}
            styles={styles}
            layoutId={`${scope}-media`}
            expanded
            pulse={progress < 100}
            className="text-background/90 dark:text-primary"
          >
            <ActivityIcon activity={activity} className="size-5" />
          </MediaOrb>
          <span className={styles.copy()}>
            <span className="mb-1.5 flex min-w-0 items-center justify-between gap-3">
              <p className={styles.title()}>{copy.title}</p>
              <span
                className={twMerge(
                  styles.mutedText(),
                  "font-medium text-background dark:text-primary",
                )}
              >
                <ProgressNumber value={progress} />
              </span>
            </span>
            <p className={twMerge(styles.description(), "mb-2")}>
              {copy.description}
            </p>
            <span className={styles.progressTrack()}>
              <motion.span
                className={styles.progressFill()}
                initial={{ width: 0 }}
                animate={{ width: `${progress}%` }}
                transition={
                  shouldReduceMotion
                    ? reducedTransition
                    : { type: "spring", stiffness: 420, damping: 36, mass: 0.8 }
                }
              />
            </span>
          </span>
        </>
      ) : null}

      {activity.variant === "notification" ? (
        <>
          <MediaOrb
            activity={activity}
            styles={styles}
            layoutId={`${scope}-media`}
            expanded
          >
            <ActivityIcon activity={activity} className="size-5" />
          </MediaOrb>
          <CopyBlock activity={activity} styles={styles} eyebrow={copy.time} />
          {activity.actions ? (
            <span className={styles.actions()}>{activity.actions}</span>
          ) : (
            <span className={styles.statusDot()} aria-hidden="true" />
          )}
        </>
      ) : null}

      {activity.variant === "confirm" ? (
        <>
          <MediaOrb
            activity={activity}
            styles={styles}
            layoutId={`${scope}-media`}
            expanded
          >
            <ActivityIcon activity={activity} className="size-5" />
          </MediaOrb>
          <CopyBlock activity={activity} styles={styles} eyebrow="Confirm" />
          <span className={styles.actions()}>
            <IslandActionButton
              label="Cancel"
              onClick={activity.onCancel}
              styles={styles}
            >
              <X className="size-4" aria-hidden="true" />
            </IslandActionButton>
            <IslandActionButton
              label="Confirm"
              onClick={onConfirmSuccess}
              tone="primary"
              styles={styles}
            >
              <Check className="size-4" aria-hidden="true" />
            </IslandActionButton>
          </span>
        </>
      ) : null}
    </motion.div>
  );
}

function IslandSurface({
  activity,
  mode,
  styles,
  scope,
  feedback,
  onToggle,
  onExpandFromSplit,
  onConfirmSuccess,
  onTransientBlur,
  primarySplit,
  secondarySplit,
}: {
  activity: DynamicIslandActivity;
  mode: DynamicIslandMode;
  styles: IslandStyles;
  scope: string;
  feedback: FeedbackState;
  onToggle: () => void;
  onExpandFromSplit?: () => void;
  onConfirmSuccess: () => void;
  onTransientBlur: () => void;
  primarySplit?: boolean;
  secondarySplit?: boolean;
}) {
  const shouldReduceMotion = useReducedMotion();
  const pressTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const hoverTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const longPressTriggeredRef = useRef(false);
  const hoverExpandedRef = useRef(false);
  const detailed = isDetailedMode(mode);
  const surfaceMode = mode === "split" ? "compact" : mode;

  const clearPressTimer = useCallback(() => {
    if (pressTimerRef.current) {
      clearTimeout(pressTimerRef.current);
      pressTimerRef.current = null;
    }
  }, []);

  const clearHoverTimer = useCallback(() => {
    if (hoverTimerRef.current) {
      clearTimeout(hoverTimerRef.current);
      hoverTimerRef.current = null;
    }
  }, []);

  const requestLongExpand = useCallback(() => {
    longPressTriggeredRef.current = true;
    onExpandFromSplit?.();
    if (!(onExpandFromSplit || detailed)) {
      onToggle();
    }
  }, [detailed, onExpandFromSplit, onToggle]);

  const handleClick = useCallback(() => {
    if (longPressTriggeredRef.current) {
      longPressTriggeredRef.current = false;
      return;
    }

    hoverExpandedRef.current = false;

    if (onExpandFromSplit) {
      onExpandFromSplit();
      return;
    }

    onToggle();
  }, [onExpandFromSplit, onToggle]);

  const handleKeyDown = useCallback(
    (event: KeyboardEvent<HTMLDivElement>) => {
      if (event.key !== "Enter" && event.key !== " ") {
        return;
      }

      event.preventDefault();
      handleClick();
    },
    [handleClick],
  );

  useEffect(() => {
    return () => {
      clearPressTimer();
      clearHoverTimer();
    };
  }, [clearHoverTimer, clearPressTimer]);

  return (
    <motion.div
      layout
      layoutId={`${scope}-surface`}
      role="button"
      tabIndex={0}
      aria-expanded={detailed}
      aria-label={getAriaLabel(activity, surfaceMode)}
      className={twMerge(
        styles.island(),
        getModeClassName(surfaceMode, styles),
        primarySplit ? styles.splitPrimary() : undefined,
        secondarySplit ? styles.splitSecondary() : undefined,
      )}
      onClick={handleClick}
      onKeyDown={handleKeyDown}
      onPointerDown={() => {
        clearPressTimer();
        pressTimerRef.current = setTimeout(requestLongExpand, 420);
      }}
      onPointerUp={clearPressTimer}
      onPointerCancel={clearPressTimer}
      onMouseEnter={() => {
        if (detailed || onExpandFromSplit) {
          return;
        }
        clearHoverTimer();
        hoverTimerRef.current = setTimeout(() => {
          hoverExpandedRef.current = true;
          onToggle();
        }, 260);
      }}
      onMouseLeave={() => {
        clearHoverTimer();

        if (hoverExpandedRef.current && isDetailedMode(surfaceMode)) {
          hoverTimerRef.current = setTimeout(() => {
            hoverExpandedRef.current = false;
            onToggle();
          }, 140);
        }
      }}
      onBlur={(event) => {
        if (!event.currentTarget.contains(event.relatedTarget)) {
          hoverExpandedRef.current = false;
          onTransientBlur();
        }
      }}
      initial={shouldReduceMotion ? false : { opacity: 0, scale: 0.985, y: 4 }}
      animate={{ opacity: 1, scale: 1, y: 0 }}
      exit={
        shouldReduceMotion ? undefined : { opacity: 0, scale: 0.985, y: -4 }
      }
      whileTap={shouldReduceMotion ? undefined : { scale: 0.996 }}
      transition={shouldReduceMotion ? reducedTransition : islandTransition}
    >
      <AnimatePresence mode="wait" initial={false}>
        {isDetailedMode(surfaceMode) ? (
          <ExpandedContent
            key={`${scope}-expanded-${feedback ?? activity.variant}`}
            activity={activity}
            styles={styles}
            scope={scope}
            feedback={feedback}
            onConfirmSuccess={onConfirmSuccess}
          />
        ) : (
          <CompactContent
            key={`${scope}-${surfaceMode}-${feedback ?? activity.variant}`}
            activity={activity}
            mode={surfaceMode}
            styles={styles}
            scope={scope}
            feedback={feedback}
          />
        )}
      </AnimatePresence>
    </motion.div>
  );
}

export function DynamicIsland({
  variant = "notification",
  size = "md",
  mode,
  defaultMode = "compact",
  autoCollapse = true,
  autoCollapseDelay = 3200,
  secondaryActivity,
  onModeChange,
  title,
  description,
  time,
  progress = 0,
  image,
  isPlaying = false,
  isActive = false,
  onPlayPause,
  onConfirm,
  onCancel,
  onStop,
  actions,
  icon,
  className,
  ...props
}: DynamicIslandProps) {
  const styles = dynamicIslandVariants({ size });
  const [internalMode, setInternalMode] =
    useState<DynamicIslandMode>(defaultMode);
  const [activeSource, setActiveSource] = useState<"primary" | "secondary">(
    "primary",
  );
  const [feedback, setFeedback] = useState<FeedbackState>(null);
  const collapseTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const progressCompleteRef = useRef(false);
  const currentMode = mode ?? internalMode;

  const primaryActivity = useMemo(
    () =>
      normalizeActivity({
        variant,
        title,
        description,
        time,
        progress,
        image,
        isPlaying,
        isActive,
        onPlayPause,
        onConfirm,
        onCancel,
        onStop,
        actions,
        icon,
      }),
    [
      actions,
      description,
      icon,
      image,
      isActive,
      isPlaying,
      onCancel,
      onConfirm,
      onPlayPause,
      onStop,
      progress,
      time,
      title,
      variant,
    ],
  );

  const secondary = useMemo(
    () => normalizeActivity(secondaryActivity),
    [secondaryActivity],
  );

  const activeActivity =
    activeSource === "secondary" && secondaryActivity
      ? secondary
      : primaryActivity;

  const requestMode = useCallback(
    (nextMode: DynamicIslandMode) => {
      if (!mode) {
        setInternalMode(nextMode);
      }

      if (nextMode !== currentMode) {
        onModeChange?.(nextMode);
      }
    },
    [currentMode, mode, onModeChange],
  );

  const collapseTransient = useCallback(() => {
    if (currentMode === "transient") {
      requestMode("compact");
    }
  }, [currentMode, requestMode]);

  const toggleMode = useCallback(() => {
    setFeedback(null);
    requestMode(isDetailedMode(currentMode) ? "compact" : "expanded");
  }, [currentMode, requestMode]);

  const confirmWithSuccess = useCallback(() => {
    activeActivity.onConfirm?.();
    setFeedback("success");
    requestMode("transient");
  }, [activeActivity, requestMode]);

  useEffect(() => {
    if (!autoCollapse || currentMode !== "transient") {
      return;
    }

    if (collapseTimerRef.current) {
      clearTimeout(collapseTimerRef.current);
    }

    collapseTimerRef.current = setTimeout(() => {
      setFeedback(null);
      requestMode("compact");
    }, autoCollapseDelay);

    return () => {
      if (collapseTimerRef.current) {
        clearTimeout(collapseTimerRef.current);
      }
    };
  }, [autoCollapse, autoCollapseDelay, currentMode, requestMode]);

  useEffect(() => {
    if (activeActivity.variant !== "progress") {
      progressCompleteRef.current = false;
      return;
    }

    const value = clampProgress(activeActivity.progress);

    if (value < 100) {
      progressCompleteRef.current = false;
      if (feedback === "success") {
        setFeedback(null);
      }
      return;
    }

    if (!progressCompleteRef.current) {
      progressCompleteRef.current = true;
      setFeedback("success");
      requestMode("transient");
    }
  }, [activeActivity, feedback, requestMode]);

  const showSplit = currentMode === "split" && Boolean(secondaryActivity);

  return (
    <div
      data-slot="dynamic-island"
      className={twMerge(styles.root(), className)}
      {...props}
    >
      <AnimatePresence mode="popLayout" initial={false}>
        {showSplit ? (
          <motion.div
            key="split"
            layout
            className={styles.splitGroup()}
            transition={islandTransition}
          >
            <IslandSurface
              activity={primaryActivity}
              mode="compact"
              styles={styles}
              scope="dynamic-island-primary"
              feedback={feedback}
              primarySplit
              onToggle={toggleMode}
              onExpandFromSplit={() => {
                setActiveSource("primary");
                setFeedback(null);
                requestMode("expanded");
              }}
              onConfirmSuccess={confirmWithSuccess}
              onTransientBlur={collapseTransient}
            />
            <IslandSurface
              activity={secondary}
              mode="minimal"
              styles={styles}
              scope="dynamic-island-secondary"
              feedback={null}
              secondarySplit
              onToggle={toggleMode}
              onExpandFromSplit={() => {
                setActiveSource("secondary");
                setFeedback(null);
                requestMode("expanded");
              }}
              onConfirmSuccess={confirmWithSuccess}
              onTransientBlur={collapseTransient}
            />
          </motion.div>
        ) : (
          <IslandSurface
            key={`${activeSource}-single`}
            activity={activeActivity}
            mode={currentMode}
            styles={styles}
            scope={`dynamic-island-${activeSource}`}
            feedback={feedback}
            onToggle={toggleMode}
            onConfirmSuccess={confirmWithSuccess}
            onTransientBlur={collapseTransient}
          />
        )}
      </AnimatePresence>
    </div>
  );
}

"use client";

import { AnimatePresence, type HTMLMotionProps, motion } from "framer-motion";
import { ChevronDown } from "lucide-react";
import * as React from "react";

import { cn } from "@/lib/utils";

type AccordionContextType = {
  openItems: string[];
  toggleItem: (value: string) => void;
};

const AccordionContext = React.createContext<AccordionContextType | null>(null);

export interface AccordionProps extends React.ComponentProps<"div"> {
  children: React.ReactNode;
}

export function Accordion({ children, className, ...props }: AccordionProps) {
  const [openItems, setOpenItems] = React.useState<string[]>([]);

  const toggleItem = React.useCallback((value: string) => {
    setOpenItems((prev) =>
      prev.includes(value) ? prev.filter((i) => i !== value) : [...prev, value],
    );
  }, []);

  const value = React.useMemo(
    () => ({ openItems, toggleItem }),
    [openItems, toggleItem],
  );

  return (
    <AccordionContext.Provider value={value}>
      <div
        data-slot="accordion"
        className={cn("w-full space-y-2", className)}
        {...props}
      >
        {children}
      </div>
    </AccordionContext.Provider>
  );
}

export interface AccordionItemProps extends HTMLMotionProps<"div"> {
  value: string;
  children: React.ReactNode;
}

export function AccordionItem({
  value: _value,
  children,
  className,
  ...props
}: AccordionItemProps) {
  return (
    <motion.div
      layout
      data-slot="accordion-item"
      className={cn(
        "overflow-hidden rounded-xl border border-border bg-card",
        className,
      )}
      {...props}
    >
      {children}
    </motion.div>
  );
}

export interface AccordionTriggerProps extends React.ComponentProps<"button"> {
  value: string;
  children: React.ReactNode;
}

export function AccordionTrigger({
  value,
  children,
  className,
  ...props
}: AccordionTriggerProps) {
  const context = React.useContext(AccordionContext);
  if (!context)
    throw new Error("AccordionTrigger must be used within Accordion");

  const isOpen = context.openItems.includes(value);

  const handleKeyDown = React.useCallback(
    (e: React.KeyboardEvent<HTMLButtonElement>) => {
      if (e.key === "Enter" || e.key === " ") {
        e.preventDefault();
        context.toggleItem(value);
      }
    },
    [context, value],
  );

  return (
    <button
      type="button"
      data-slot="accordion-trigger"
      data-state={isOpen ? "open" : "closed"}
      aria-expanded={isOpen}
      onClick={() => context.toggleItem(value)}
      onKeyDown={handleKeyDown}
      className={cn(
        "flex w-full items-center justify-between px-4 py-2 text-left outline-none transition-colors",
        "focus-visible:ring-2 focus-visible:ring-ring",
        isOpen ? "bg-accent" : "hover:bg-accent",
        className,
      )}
      {...props}
    >
      <div className="flex flex-col">
        <span className="text-sm font-medium text-foreground">{children}</span>
      </div>
      <motion.div
        animate={{ rotate: isOpen ? 180 : 0 }}
        transition={{ type: "spring", stiffness: 260, damping: 20 }}
      >
        <ChevronDown className="size-4 text-muted-foreground" aria-hidden />
      </motion.div>
    </button>
  );
}

export interface AccordionContentProps extends HTMLMotionProps<"div"> {
  value: string;
  children: React.ReactNode;
}

export function AccordionContent({
  value,
  children,
  className,
  ...props
}: AccordionContentProps) {
  const context = React.useContext(AccordionContext);
  if (!context)
    throw new Error("AccordionContent must be used within Accordion");

  const isOpen = context.openItems.includes(value);

  return (
    <AnimatePresence initial={false}>
      {isOpen && (
        <motion.div
          layout
          data-slot="accordion-content"
          initial={{ height: 0, opacity: 0 }}
          animate={{ height: "auto", opacity: 1 }}
          exit={{ height: 0, opacity: 0 }}
          transition={{ type: "spring", stiffness: 260, damping: 25 }}
          className={cn("overflow-hidden", className)}
          {...props}
        >
          <div className="bg-accent px-4 pb-4 pt-2 text-sm leading-relaxed text-muted-foreground">
            {children}
          </div>
        </motion.div>
      )}
    </AnimatePresence>
  );
}

