function getNeighborScale(index: number, activeIndex: number | null) {
  if (activeIndex === null) {
    return 1;
  }

  const distance = Math.abs(index - activeIndex);

  if (distance === 0) {
    return 1.16;
  }

  if (distance === 1) {
    return 1.075;
  }

  if (distance === 2) {
    return 1.025;
  }

  return 1;
}

export function CommandDock({
