        </Button>
      </div>

      {isEnabled && (
        <ActionBar
          placement="bottomCenter"
          tone="destructive"
          subject="Meu Workspace"
          icon={<Trash2 className="size-4 text-destructive" aria-hidden />}
          confirmLabel="Excluir"
          confirmLabelLoading="Excluindo..."
          actions={{
            onCancel: () => setIsEnabled(false),
            onConfirm: handleConfirm,
            isLoading,
          }}
        />
      )}
    </div>
  );
}

