} from "@/components/matos-ui/file-upload";

function createDemoFile(
  name: string,
  size: number,
  type: string,
  status: FileUploadFile["status"],
  progress?: number,
  error?: string,
): FileUploadFile {
  return {
    id: name,
    file: new File([new Uint8Array(size)], name, {
      type,
      lastModified: Date.now(),
    }),
    status,
    progress,
    error,
  };
}

